   270→// ============================================================================
   271→// Part 4: 부트로더 (Bootloader)
   272→// ============================================================================
   273→
   274→/// 부트 정보
   275→pub struct BootInfo {
   276→    /// 총 물리 메모리 (MB)
   277→    pub total_memory_mb: u64,
   278→
   279→    /// 커널 로드 주소
   280→    pub kernel_load_addr: u64,
   281→
   282→    /// 커널 크기 (바이트)
   283→    pub kernel_size: u64,
   284→
   285→    /// 사용 가능한 메모리 시작 주소
   286→    pub available_memory_start: u64,
   287→
   288→    /// 사용 가능한 메모리 끝 주소
   289→    pub available_memory_end: u64,
   290→}
   291→
   292→impl BootInfo {
   293→    pub fn new() -> Self {
   294→        BootInfo {
   295→            total_memory_mb: 512,  // 512 MB 메모리 가정
   296→            kernel_load_addr: 0x100000,  // 1MB에서 시작
   297→            kernel_size: 0x100000,  // 1MB 크기
   298→            available_memory_start: 0x200000,  // 2MB부터 사용 가능
   299→            available_memory_end: 0x20000000,  // 512MB까지
   300→        }
   301→    }
   302→
   303→    pub fn total_available_memory(&self) -> u64 {
   304→        self.available_memory_end - self.available_memory_start
   305→    }
   306→}
   307→
   308→// ============================================================================
   309→// Part 5: 초기화 함수들
   310→// ============================================================================
   311→
   312→/// 부트로더 초기화
   313→pub fn init_bootloader() -> BootInfo {
   314→    println!("🔧 Initializing FreeLang OS Bootloader...");
   315→
   316→    let boot_info = BootInfo::new();
   317→    println!("✅ Boot info created:");
   318→    println!("   Total Memory: {} MB", boot_info.total_memory_mb);
   319→    println!("   Kernel Load Addr: 0x{:x}", boot_info.kernel_load_addr);
   320→    println!("   Available Memory: 0x{:x} - 0x{:x}",
   321→             boot_info.available_memory_start,
   322→             boot_info.available_memory_end);
   323→
   324→    boot_info
   325→}
   326→
   327→/// 페이징 시스템 초기화
   328→pub fn init_paging() -> PageTable {
   329→    println!("\n📄 Initializing Paging System...");
   330→
   331→    let mut page_table = PageTable::new(0);  // Kernel process ID = 0
   332→
   333→    // 커널 메모리 영역 매핑 (0x100000 ~ 0x200000)
   334→    for i in 0..256 {
   335→        let virtual_addr = 0x100000 + (i * 4096);
   336→        let physical_addr = 0x100000 + (i * 4096);
   337→        page_table.map_page(virtual_addr, physical_addr);
   338→    }
   339→
   340→    println!("✅ Paging initialized with {} page table entries", page_table.entries.len());
   341→    page_table
   342→}
   343→
   344→/// 힙 할당자 초기화
   345→pub fn init_heap_allocator(boot_info: &BootInfo) -> HeapAllocator {
   346→    println!("\n💾 Initializing Heap Allocator...");
   347→
   348→    let heap_start = boot_info.available_memory_start;
   349→    let heap_size = boot_info.total_available_memory();
   350→
   351→    let allocator = HeapAllocator::new(heap_start, heap_size);
   352→    println!("✅ Heap allocated: 0x{:x}, Size: {} MB",
   353→             heap_start, heap_size / 1024 / 1024);
   354→
   355→    allocator
   356→}
   357→
   358→// ============================================================================
   359→// Part 6: 메인 부트로더 진입점
   360→// ============================================================================
   361→
   362→pub fn main() {
   363→    println!("╔════════════════════════════════════════════════════════════╗");
   364→    println!("║     FreeLang OS Kernel - Phase G Week 1 Bootloader        ║");
   365→    println!("╚════════════════════════════════════════════════════════════╝\n");
   366→
   367→    // Step 1: 부트 정보 초기화
   368→    let boot_info = init_bootloader();
   369→
   370→    // Step 2: 페이징 시스템 초기화
   371→    let page_table = init_paging();
   372→
   373→    // Step 3: 힙 할당자 초기화
   374→    let mut heap_allocator = init_heap_allocator(&boot_info);
   375→
   376→    // Step 4: 메모리 할당 테스트
   377→    println!("\n🧪 Testing Memory Allocation...");
   378→
   379→    if let Some(addr1) = heap_allocator.allocate(4096) {
   380→        println!("✅ Allocated 4KB block at 0x{:x}", addr1);
   381→    }
   382→
   383→    if let Some(addr2) = heap_allocator.allocate(8192) {
   384→        println!("✅ Allocated 8KB block at 0x{:x}", addr2);
   385→    }
   386→
   387→    println!("   Total allocated: {} bytes", heap_allocator.allocated_size);
   388→    println!("   Fragmentation ratio: {:.2}%",
   389→             heap_allocator.fragmentation_ratio() * 100.0);
   390→
   391→    // Step 5: 가상 주소 변환 테스트
   392→    println!("\n🔍 Testing Virtual Address Translation...");
   393→
   394→    let test_vaddr = 0x100000;
   395→    if let Some(paddr) = page_table.translate_virtual_address(test_vaddr) {
   396→        println!("✅ Virtual 0x{:x} → Physical 0x{:x}", test_vaddr, paddr);
   397→    } else {
   398→        println!("❌ Translation failed for 0x{:x}", test_vaddr);
   399→    }
   400→
   401→    println!("\n✨ Bootloader initialization complete!");
   402→    println!("Ready to load kernel...\n");
   403→}
