   466→
   467→        if let Some(addr) = allocator.allocate(4096) {
   468→            assert!(allocator.deallocate(addr));
   469→            assert_eq!(allocator.allocated_size, 0);
   470→        }
   471→    }
   472→
   473→    #[test]
   474→    fn test_boot_info() {
