    14→/// x86-64 일반 목적 레지스터
    15→pub struct GeneralPurposeRegisters {
    16→    /// RAX: 누적기
    17→    pub rax: u64,
    18→    /// RBX: 기본
    19→    pub rbx: u64,
    20→    /// RCX: 카운터
    21→    pub rcx: u64,
    22→    /// RDX: 데이터
    23→    pub rdx: u64,
    24→    /// RSI: 소스 인덱스
    25→    pub rsi: u64,
    26→    /// RDI: 목적지 인덱스
    27→    pub rdi: u64,
    28→    /// RBP: 베이스 포인터
    29→    pub rbp: u64,
    30→    /// RSP: 스택 포인터
    31→    pub rsp: u64,
    32→}
    33→
    34→impl GeneralPurposeRegisters {
    35→    pub fn new() -> Self {
    36→        GeneralPurposeRegisters {
    37→            rax: 0,
    38→            rbx: 0,
    39→            rcx: 0,
    40→            rdx: 0,
    41→            rsi: 0,
    42→            rdi: 0,
    43→            rbp: 0,
    44→            rsp: 0,
    45→        }
    46→    }
    47→
    48→    pub fn initialize_for_process(stack_addr: u64) -> Self {
    49→        let mut regs = GeneralPurposeRegisters::new();
    50→        regs.rsp = stack_addr;  // 스택 포인터 초기화
    51→        regs.rbp = stack_addr;  // 베이스 포인터 초기화
    52→        regs
    53→    }
    54→
    55→    pub fn get_all_registers(&self) -> [u64; 8] {
    56→        [
    57→            self.rax, self.rbx, self.rcx, self.rdx,
    58→            self.rsi, self.rdi, self.rbp, self.rsp,
    59→        ]
    60→    }
    61→
    62→    pub fn set_all_registers(&mut self, values: [u64; 8]) {
    63→        self.rax = values[0];
    64→        self.rbx = values[1];
    65→        self.rcx = values[2];
    66→        self.rdx = values[3];
    67→        self.rsi = values[4];
    68→        self.rdi = values[5];
    69→        self.rbp = values[6];
    70→        self.rsp = values[7];
    71→    }
    72→
    73→    pub fn print_registers(&self) {
    74→        println!("RAX: 0x{:016x} | RBX: 0x{:016x}", self.rax, self.rbx);
    75→        println!("RCX: 0x{:016x} | RDX: 0x{:016x}", self.rcx, self.rdx);
    76→        println!("RSI: 0x{:016x} | RDI: 0x{:016x}", self.rsi, self.rdi);
    77→        println!("RBP: 0x{:016x} | RSP: 0x{:016x}", self.rbp, self.rsp);
    78→    }
    79→}
    80→
    81→/// CPU 플래그 (RFLAGS)
    82→pub struct CPUFlags {
    83→    /// Carry Flag
    84→    pub carry: bool,
    85→    /// Zero Flag
    86→    pub zero: bool,
    87→    /// Sign Flag
    88→    pub sign: bool,
    89→    /// Overflow Flag
    90→    pub overflow: bool,
    91→    /// Interrupt Enable Flag
    92→    pub interrupt_enable: bool,
    93→}
    94→
    95→impl CPUFlags {
    96→    pub fn new() -> Self {
    97→        CPUFlags {
    98→            carry: false,
    99→            zero: false,
   100→            sign: false,
   101→            overflow: false,
   102→            interrupt_enable: true,
   103→        }
   104→    }
   105→
   106→    pub fn to_u64(&self) -> u64 {
   107→        let mut flags: u64 = 0;
   108→        if self.carry { flags |= 1 << 0; }
   109→        if self.zero { flags |= 1 << 6; }
   110→        if self.sign { flags |= 1 << 7; }
   111→        if self.overflow { flags |= 1 << 11; }
   112→        if self.interrupt_enable { flags |= 1 << 9; }
   113→        flags
   114→    }
   115→
   116→    pub fn from_u64(flags: u64) -> Self {
   117→        CPUFlags {
   118→            carry: (flags & (1 << 0)) != 0,
   119→            zero: (flags & (1 << 6)) != 0,
   120→            sign: (flags & (1 << 7)) != 0,
   121→            overflow: (flags & (1 << 11)) != 0,
   122→            interrupt_enable: (flags & (1 << 9)) != 0,
   123→        }
   124→    }
   125→}
