   350→// ============================================================================
   351→// Part 4: 컨텍스트 스위처 (Context Switcher)
   352→// ============================================================================
   353→
   354→/// 컨텍스트 전환 정보
   355→pub struct ContextSwitchInfo {
   356→    /// 이전 프로세스 ID
   357→    pub prev_pid: u32,
   358→
   359→    /// 다음 프로세스 ID
   360→    pub next_pid: u32,
   361→
   362→    /// 전환 시간 (ms)
   363→    pub switch_time_ms: u32,
   364→
   365→    /// 이전 프로세스의 컨텍스트
   366→    pub prev_context: ProcessContext,
   367→
   368→    /// 다음 프로세스의 컨텍스트
   369→    pub next_context: ProcessContext,
   370→}
   371→
   372→pub struct ContextSwitcher {
   373→    /// 마지막 컨텍스트 전환 정보
   374→    pub last_switch: Option<ContextSwitchInfo>,
   375→
   376→    /// 총 컨텍스트 전환 횟수
   377→    pub total_switches: u64,
   378→
   379→    /// 컨텍스트 전환 누적 시간 (ns)
   380→    pub total_switch_time_ns: u64,
   381→}
   382→
   383→impl ContextSwitcher {
   384→    pub fn new() -> Self {
   385→        ContextSwitcher {
   386→            last_switch: None,
   387→            total_switches: 0,
   388→            total_switch_time_ns: 0,
   389→        }
   390→    }
   391→
   392→    pub fn switch_context(&mut self, prev_pid: u32, prev_context: ProcessContext,
   393→                          next_pid: u32, mut next_context: ProcessContext,
   394→                          switch_time_ms: u32) {
   395→        // 이전 프로세스 컨텍스트 저장
   396→        // (실제로는 메모리에 저장하지만, 여기서는 시뮬레이션)
   397→
   398→        // 다음 프로세스 컨텍스트 복원
   399→        next_context.record_switch();
   400→
   401→        let switch_info = ContextSwitchInfo {
   402→            prev_pid,
   403→            next_pid,
   404→            switch_time_ms,
   405→            prev_context,
   406→            next_context,
   407→        };
   408→
   409→        self.last_switch = Some(switch_info);
   410→        self.total_switches += 1;
   411→        self.total_switch_time_ns += switch_time_ms as u64 * 1_000_000;  // ms → ns
   412→    }
   413→
   414→    pub fn get_last_switch(&self) -> Option<&ContextSwitchInfo> {
   415→        self.last_switch.as_ref()
   416→    }
   417→
   418→    pub fn average_switch_time_us(&self) -> f64 {
   419→        if self.total_switches == 0 {
   420→            return 0.0;
   421→        }
   422→        (self.total_switch_time_ns as f64) / (self.total_switches as f64) / 1000.0
   423→    }
   424→
   425→    pub fn print_statistics(&self) {
   426→        println!("\n⚡ Context Switch Statistics:");
   427→        println!("  Total Switches: {}", self.total_switches);
   428→        println!("  Total Time: {} ns", self.total_switch_time_ns);
   429→        println!("  Average Switch Time: {:.2} µs", self.average_switch_time_us());
   430→
   431→        if let Some(last_switch) = &self.last_switch {
   432→            println!("\n  Last Context Switch:");
   433→            println!("    {} → {}", last_switch.prev_pid, last_switch.next_pid);
   434→            println!("    Switch Time: {}ms", last_switch.switch_time_ms);
   435→        }
   436→    }
   437→}
