   487→pub fn main() {
   488→    println!("╔════════════════════════════════════════════════════════════╗");
   489→    println!("║  FreeLang OS Kernel - Phase G Week 2 Context Switching     ║");
   490→    println!("╚════════════════════════════════════════════════════════════╝\n");
   491→
   492→    // 스케줄러 생성
   493→    let mut scheduler = RoundRobinScheduler::new();
   494→    let mut switcher = ContextSwitcher::new();
   495→
   496→    println!("✅ Scheduler initialized");
   497→    println!("   Default Time Slice: {}ms\n", scheduler.default_time_slice_ms);
   498→
   499→    // 프로세스 생성 및 추가
   500→    println!("🔄 Creating processes...");
   501→
   502→    let mut ctx1 = ProcessContext::new(1, 0x100000, 0x7FFFF000);
   503→    ctx1.registers.rax = 42;
   504→    scheduler.add_process(1, ctx1);
   505→    println!("   ✅ Process 1 added");
   506→
   507→    let mut ctx2 = ProcessContext::new(2, 0x110000, 0x7FFFE000);
   508→    ctx2.registers.rax = 100;
   509→    scheduler.add_process(2, ctx2);
   510→    println!("   ✅ Process 2 added");
   511→
   512→    let mut ctx3 = ProcessContext::new(3, 0x120000, 0x7FFFCD000);
   513→    ctx3.registers.rax = 200;
   514→    scheduler.add_process(3, ctx3);
   515→    println!("   ✅ Process 3 added");
   516→
   517→    // 스케줄링 시뮬레이션
   518→    println!("\n⏱️  Scheduling simulation (5 time slices)...\n");
   519→
   520→    for round in 0..5 {
   521→        println!("Round {}:", round + 1);
   522→
   523→        if let Some((pid, context)) = scheduler.get_current_process() {
   524→            println!("  ▶️  Running Process {}", pid);
   525→            println!("     RIP: 0x{:x}, RAX: {}", context.instruction_pointer, context.registers.rax);
   526→        }
   527→
   528→        // 타임 슬라이스 사용
   529→        scheduler.consume_time(4);
   530→
   531→        // 다음 프로세스로 전환
   532→        if let Some((next_pid, next_context)) = scheduler.schedule_next() {
   533→            if let Some((prev_pid, _)) = scheduler.get_current_process() {
   534→                println!("  ⏸️  Switching {} → {}", prev_pid, next_pid);
   535→                switcher.switch_context(prev_pid, next_context.clone(), next_pid, next_context, 1);
   536→            }
   537→        }
   538→
   539→        println!();
   540→    }
   541→
   542→    // 상태 출력
   543→    scheduler.print_queue_status();
   544→    switcher.print_statistics();
   545→
   546→    println!("\n✨ Scheduling simulation complete!\n");
   547→}
