   681→        let ctx2 = ProcessContext::new(2, 0x110000, 0x7FFEE000);
   682→
   683→        scheduler.add_process(1, ctx1);
   684→        scheduler.add_process(2, ctx2);
   685→
   686→        for _ in 0..4 {
   687→            scheduler.consume_time(4);
   688→            scheduler.schedule_next();
   689→        }
   690→
   691→        assert!(scheduler.tick_count > 0);
   692→        assert!(scheduler.context_switch_count > 0);
   693→    }
   694→}
