   202→}
   203→
   204→pub struct SyscallHandler {
   205→    pub syscall_type: SyscallType,
   206→    pub arg1: u64,
   207→    pub arg2: u64,
   208→    pub arg3: u64,
   209→}
   210→
   211→impl SyscallHandler {
   212→    pub fn new(syscall_type: SyscallType, arg1: u64, arg2: u64, arg3: u64) -> Self {
   213→        SyscallHandler {
   214→            syscall_type,
   215→            arg1,
   216→            arg2,
   217→            arg3,
   218→        }
   219→    }
   220→
   221→    pub fn execute(&self) -> Result<u64, String> {
   222→        match self.syscall_type {
   223→            SyscallType::PrintString => {
   224→                println!("📝 Syscall: PrintString");
   225→                Ok(0)
   226→            }
   227→            SyscallType::Allocate => {
   228→                println!("💾 Syscall: Allocate({} bytes)", self.arg1);
   229→                Ok(self.arg1)
   230→            }
   231→            SyscallType::Deallocate => {
   232→                println!("🗑️  Syscall: Deallocate(0x{:x})", self.arg1);
   233→                Ok(0)
   234→            }
   235→            SyscallType::CreateProcess => {
   236→                println!("🔄 Syscall: CreateProcess(pc=0x{:x})", self.arg1);
   237→                Ok(1)  // 새 프로세스 ID
   238→            }
   239→            SyscallType::Exit => {
   240→                println!("🛑 Syscall: Exit({})", self.arg1);
   241→                Ok(0)
   242→            }
   243→        }
   244→    }
   245→}
