    11→// Part 1: 프로세스 작업 (Task)
    12→// ============================================================================
    13→
    14→/// 프로세스가 실행할 작업
    15→pub enum TaskType {
    16→    /// CPU 집약적 작업
    17→    ComputeIntensive { iterations: u32 },
    18→
    19→    /// I/O 대기 작업
    20→    IOWait { wait_time_ms: u32 },
    21→
    22→    /// 메모리 접근 작업
    23→    MemoryAccess { addresses: u32 },
    24→
    25→    /// 혼합 작업
    26→    Mixed { compute: u32, io_wait: u32 },
    27→}
    28→
    29→pub struct Task {
    30→    /// 작업 타입
    31→    pub task_type: TaskType,
    32→
    33→    /// 완료된 작업량
    34→    pub completed: u32,
    35→
    36→    /// 총 필요한 작업량
    37→    pub total: u32,
    38→
    39→    /// 작업 시작 시간 (시뮬레이션 틱)
    40→    pub start_tick: u32,
    41→
    42→    /// 작업 완료 시간
    43→    pub end_tick: Option<u32>,
    44→}
    45→
    46→impl Task {
    47→    pub fn new(task_type: TaskType) -> Self {
    48→        let total = match &task_type {
    49→            TaskType::ComputeIntensive { iterations } => *iterations,
    50→            TaskType::IOWait { wait_time_ms } => *wait_time_ms,
    51→            TaskType::MemoryAccess { addresses } => *addresses,
    52→            TaskType::Mixed { compute, io_wait } => compute + io_wait,
    53→        };
    54→
    55→        Task {
    56→            task_type,
    57→            completed: 0,
    58→            total,
    59→            start_tick: 0,
    60→            end_tick: None,
    61→        }
    62→    }
    63→
    64→    pub fn execute(&mut self, work_units: u32) -> bool {
    65→        if self.completed < self.total {
    66→            self.completed += work_units;
    67→            if self.completed >= self.total {
    68→                return true;  // 작업 완료
    69→            }
    70→        }
    71→        false  // 아직 실행 중
    72→    }
    73→
    74→    pub fn progress_percent(&self) -> u32 {
    75→        if self.total == 0 {
    76→            return 100;
    77→        }
    78→        (self.completed * 100) / self.total
    79→    }
    80→
    81→    pub fn is_completed(&self) -> bool {
    82→        self.completed >= self.total
    83→    }
    84→}
    85→
