    87→// Part 2: 프로세스 상태 추적
    88→// ============================================================================
    89→
    90→/// 프로세스의 성능 메트릭
    91→pub struct ProcessMetrics {
    92→    /// 프로세스 ID
    93→    pub pid: u32,
    94→
    95→    /// 총 실행 시간 (틱)
    96→    pub total_time: u32,
    97→
    98→    /// CPU 사용 시간 (틱)
    99→    pub cpu_time: u32,
   100→
   101→    /// I/O 대기 시간 (틱)
   102→    pub io_wait_time: u32,
   103→
   104→    /// 컨텍스트 스위치 횟수
   105→    pub context_switches: u32,
   106→
   107→    /// 실행 횟수
   108→    pub execution_count: u32,
   109→
   110→    /// 완료된 작업 수
   111→    pub completed_tasks: u32,
   112→}
   113→
   114→impl ProcessMetrics {
   115→    pub fn new(pid: u32) -> Self {
   116→        ProcessMetrics {
   117→            pid,
   118→            total_time: 0,
   119→            cpu_time: 0,
   120→            io_wait_time: 0,
   121→            context_switches: 0,
   122→            execution_count: 0,
   123→            completed_tasks: 0,
   124→        }
   125→    }
   126→
   127→    pub fn cpu_utilization(&self) -> f64 {
   128→        if self.total_time == 0 {
   129→            return 0.0;
   130→        }
   131→        (self.cpu_time as f64 / self.total_time as f64) * 100.0
   132→    }
   133→
   134→    pub fn io_utilization(&self) -> f64 {
   135→        if self.total_time == 0 {
   136→            return 0.0;
   137→        }
   138→        (self.io_wait_time as f64 / self.total_time as f64) * 100.0
   139→    }
   140→
   141→    pub fn record_execution(&mut self, cpu_time: u32, io_time: u32) {
   142→        self.cpu_time += cpu_time;
   143→        self.io_wait_time += io_time;
   144→        self.total_time += cpu_time + io_time;
   145→        self.execution_count += 1;
   146→    }
   147→
   148→    pub fn record_context_switch(&mut self) {
   149→        self.context_switches += 1;
   150→    }
   151→
   152→    pub fn record_task_completion(&mut self) {
   153→        self.completed_tasks += 1;
   154→    }
   155→
   156→    pub fn print_metrics(&self) {
   157→        println!("\n📊 Process {} Metrics:", self.pid);
   158→        println!("  Total Time: {} ticks", self.total_time);
   159→        println!("  CPU Time: {} ticks ({:.2}%)", self.cpu_time, self.cpu_utilization());
   160→        println!("  I/O Wait: {} ticks ({:.2}%)", self.io_wait_time, self.io_utilization());
   161→        println!("  Context Switches: {}", self.context_switches);
   162→        println!("  Executions: {}", self.execution_count);
   163→        println!("  Completed Tasks: {}", self.completed_tasks);
   164→    }
   165→}
