   170→
   171→/// 프로세스 항목
   172→pub struct ProcessEntry {
   173→    /// 프로세스 ID
   174→    pub pid: u32,
   175→
   176→    /// 현재 작업
   177→    pub current_task: Task,
   178→
   179→    /// 메트릭
   180→    pub metrics: ProcessMetrics,
   181→
   182→    /// 우선순위 (0-10, 10이 가장 높음)
   183→    pub priority: u8,
   184→
   185→    /// 상태 (Ready/Running/Blocked)
   186→    pub state: String,
   187→}
   188→
   189→impl ProcessEntry {
   190→    pub fn new(pid: u32, task: Task, priority: u8) -> Self {
   191→        ProcessEntry {
   192→            pid,
   193→            current_task: task,
   194→            metrics: ProcessMetrics::new(pid),
   195→            priority,
   196→            state: "Ready".to_string(),
   197→        }
   198→    }
   199→}
   200→
   201→/// 멀티태스킹 시스템
   202→pub struct MultitaskingSystem {
   203→    /// 프로세스들
   204→    pub processes: Vec<ProcessEntry>,
   205→
   206→    /// 현재 실행 중인 프로세스 인덱스
   207→    pub current_process: Option<usize>,
   208→
   209→    /// 전체 시스템 틱
   210→    pub total_ticks: u32,
   211→
   212→    /// 컨텍스트 스위치 횟수
   213→    pub context_switch_count: u32,
   214→
   215→    /// 완료된 작업 수
   216→    pub completed_tasks: u32,
   217→}
   218→
   219→impl MultitaskingSystem {
   220→    pub fn new() -> Self {
   221→        MultitaskingSystem {
   222→            processes: Vec::new(),
   223→            current_process: None,
   224→            total_ticks: 0,
   225→            context_switch_count: 0,
   226→            completed_tasks: 0,
   227→        }
   228→    }
   229→
   230→    pub fn add_process(&mut self, pid: u32, task: Task, priority: u8) {
   231→        let entry = ProcessEntry::new(pid, task, priority);
   232→        self.processes.push(entry);
   233→
   234→        if self.current_process.is_none() {
   235→            self.current_process = Some(0);
   236→        }
   237→    }
   238→
   239→    pub fn execute_round(&mut self) -> Option<(u32, String)> {
   240→        if self.processes.is_empty() {
   241→            return None;
   242→        }
   243→
   244→        // 현재 프로세스 실행
   245→        let idx = self.current_process?;
   246→        let process = &mut self.processes[idx];
   247→
   248→        if !process.current_task.is_completed() {
   249→            process.state = "Running".to_string();
   250→
   251→            // 작업 실행 (1 틱 = 일정 작업량)
   252→            let work_completed = process.current_task.execute(1);
   253→            process.metrics.record_execution(1, 0);
   254→
   255→            if work_completed {
   256→                process.metrics.record_task_completion();
   257→                self.completed_tasks += 1;
   258→                println!("  ✅ Process {} task completed ({} completed total)",
   259→                         process.pid, self.completed_tasks);
   260→            }
   261→
   262→            let status = format!("PID {} - {}% complete",
   263→                                process.pid,
   264→                                process.current_task.progress_percent());
   265→
   266→            // 다음 프로세스로 전환
   267→            let next_idx = (idx + 1) % self.processes.len();
   268→            if next_idx != idx {
   269→                self.processes[idx].metrics.record_context_switch();
   270→                self.processes[next_idx].metrics.record_context_switch();
   271→                self.context_switch_count += 1;
   272→                process.state = "Ready".to_string();
   273→                self.current_process = Some(next_idx);
   274→            }
   275→
   276→            self.total_ticks += 1;
   277→            return Some((process.pid, status));
   278→        }
   279→
   280→        // 다음 프로세스로 전환
   281→        let next_idx = (idx + 1) % self.processes.len();
   282→        self.current_process = Some(next_idx);
   283→        self.context_switch_count += 1;
   284→
   285→        self.execute_round()  // 다음 프로세스 실행
   286→    }
   287→
   288→    pub fn execute_for_time(&mut self, time_ticks: u32) {
   289→        for _ in 0..time_ticks {
   290→            if self.execute_round().is_none() {
   291→                break;
   292→            }
   293→        }
   294→    }
   295→
   296→    pub fn all_tasks_completed(&self) -> bool {
   297→        self.processes.iter().all(|p| p.current_task.is_completed())
   298→    }
   299→
   300→    pub fn print_system_status(&self) {
   301→        println!("\n╔════════════════════════════════════════════════════════════╗");
   302→        println!("║         Multitasking System Status Report                  ║");
   303→        println!("╚════════════════════════════════════════════════════════════╝");
   304→
   305→        println!("\n🔄 System Metrics:");
   306→        println!("  Total Ticks: {}", self.total_ticks);
   307→        println!("  Context Switches: {}", self.context_switch_count);
   308→        println!("  Completed Tasks: {}", self.completed_tasks);
   309→        println!("  Total Processes: {}", self.processes.len());
   310→
   311→        println!("\n📋 Process Status:");
   312→        for process in &self.processes {
   313→            let progress = process.current_task.progress_percent();
   314→            let bar = "█".repeat((progress / 10) as usize) +
   315→                     "░".repeat((10 - (progress / 10)) as usize);
   316→
   317→            println!("  PID {}: [{}] {}% - {}",
   318→                     process.pid, bar, progress, process.state);
   319→        }
   320→
   321→        println!("\n📊 Per-Process Metrics:");
   322→        for process in &self.processes {
   323→            process.metrics.print_metrics();
   324→        }
   325→    }
   326→}
