    49→            DVFSState::Mid1GHz => 250,
    50→            DVFSState::High1_5GHz => 450,
    51→            DVFSState::Max2GHz => 700,
    52→        }
    53→    }
    54→
    55→    pub fn next_state(&self) -> DVFSState {
    56→        match self {
    57→            DVFSState::Min200MHz => DVFSState::Low500MHz,
    58→            DVFSState::Low500MHz => DVFSState::Mid1GHz,
    59→            DVFSState::Mid1GHz => DVFSState::High1_5GHz,
    60→            DVFSState::High1_5GHz => DVFSState::Max2GHz,
    61→            DVFSState::Max2GHz => DVFSState::Max2GHz,
    62→        }
    63→    }
    64→
    65→    pub fn prev_state(&self) -> DVFSState {
    66→        match self {
    67→            DVFSState::Max2GHz => DVFSState::High1_5GHz,
    68→            DVFSState::High1_5GHz => DVFSState::Mid1GHz,
    69→            DVFSState::Mid1GHz => DVFSState::Low500MHz,
    70→            DVFSState::Low500MHz => DVFSState::Min200MHz,
    71→            DVFSState::Min200MHz => DVFSState::Min200MHz,
    72→        }
    73→    }
    74→}
    75→
    76→// ============================================================================
    77→// 2. 워크로드 프로필
    78→// ============================================================================
    79→
    80→pub struct WorkloadProfile {
    81→    pub ipc: f32,                 // Instructions Per Cycle (0.5-4.0)
    82→    pub cache_miss_rate: f32,     // L3 캐시 미스율 (0.0-1.0)
    83→    pub branch_mispred: f32,      // 분기 오측 률 (0.0-1.0)
    84→    pub memory_bandwidth: f32,    // 메모리 대역폭 사용률 (0.0-1.0)
    85→    pub thermal_headroom: f32,    // 열 마진 (0.0-1.0, 1.0=최대)
    86→}
    87→
    88→impl WorkloadProfile {
    89→    pub fn new(
    90→        ipc: f32,
    91→        cache_miss: f32,
    92→        branch_pred: f32,
    93→        mem_bw: f32,
    94→        thermal: f32,
    95→    ) -> Self {
    96→        WorkloadProfile {
    97→            ipc: ipc.max(0.5).min(4.0),
    98→            cache_miss_rate: cache_miss.max(0.0).min(1.0),
    99→            branch_mispred: branch_pred.max(0.0).min(1.0),
   100→            memory_bandwidth: mem_bw.max(0.0).min(1.0),
   101→            thermal_headroom: thermal.max(0.0).min(1.0),
   102→        }
   103→    }
   104→
   105→    /// 프로필 → 신경망 입력 (16차원)
   106→    pub fn to_feature_vector(&self) -> [f32; 16] {
   107→        [
   108→            self.ipc,
   109→            self.cache_miss_rate,
   110→            self.branch_mispred,
   111→            self.memory_bandwidth,
   112→            self.thermal_headroom,
   113→            self.ipc * self.cache_miss_rate,
   114→            self.ipc / (self.branch_mispred + 0.001),
   115→            self.memory_bandwidth * self.thermal_headroom,
   116→            (1.0 - self.cache_miss_rate) * self.ipc,
   117→            self.branch_mispred + self.cache_miss_rate,
   118→            self.ipc * self.thermal_headroom,
   119→            self.memory_bandwidth / (self.branch_mispred + 0.001),
   120→            0.0, 0.0, 0.0, 0.0,  // 패딩
   121→        ]
   122→    }
   123→
   124→    pub fn validate(&self) -> bool {
   125→        self.ipc >= 0.5 && self.ipc <= 4.0 &&
   126→        self.cache_miss_rate >= 0.0 && self.cache_miss_rate <= 1.0 &&
   127→        self.branch_mispred >= 0.0 && self.branch_mispred <= 1.0 &&
   128→        self.memory_bandwidth >= 0.0 && self.memory_bandwidth <= 1.0 &&
   129→        self.thermal_headroom >= 0.0 && self.thermal_headroom <= 1.0
   130→    }
   131→}
   132→
   133→// ============================================================================
   134→// 3. DVFS 예측기
   135→// ============================================================================
   136→
   137→pub struct DVFSPredictor {
   138→    pub model: L0NeuralNet,
   139→    pub current_state: DVFSState,
   140→    pub prediction_history: Vec<DVFSState>,
   141→    pub prediction_accuracy: f32,
   142→    pub error_rate: f32,
   143→    pub state_changes: u32,
   144→    pub predictions_made: u32,
   145→}
   146→
   147→impl DVFSPredictor {
   148→    pub fn new() -> Self {
   149→        let mut model = L0NeuralNet::new();
   150→        model.initialize_random();
   151→
   152→        DVFSPredictor {
   153→            model,
   154→            current_state: DVFSState::Mid1GHz,
   155→            prediction_history: Vec::new(),
   156→            prediction_accuracy: 0.0,
   157→            error_rate: 0.0,
   158→            state_changes: 0,
   159→            predictions_made: 0,
   160→        }
   161→    }
   162→
   163→    /// 워크로드 프로필에서 최적 주파수 예측
   164→    pub fn predict_optimal_freq(&mut self, workload: &WorkloadProfile) -> DVFSState {
   165→        if !workload.validate() {
   166→            return self.current_state;
   167→        }
   168→
   169→        // 신경망 입력 (16차원)
   170→        let features = workload.to_feature_vector();
   171→
   172→        // L0NN 추론 (8차원 출력 → DVFS 상태)
   173→        let output = self.model.forward(&features);
   174→
   175→        // 출력 해석: max로 상태 결정
   176→        let mut max_idx = 0usize;
   177→        let mut max_val = output[0];
   178→        for i in 1..5 {
   179→            if output[i] > max_val {
   180→                max_val = output[i];
   181→                max_idx = i;
   182→            }
   183→        }
   184→
   185→        let predicted_state = match max_idx {
   186→            0 => DVFSState::Min200MHz,
   187→            1 => DVFSState::Low500MHz,
   188→            2 => DVFSState::Mid1GHz,
   189→            3 => DVFSState::High1_5GHz,
   190→            _ => DVFSState::Max2GHz,
   191→        };
   192→
   193→        // 열 제약 확인
   194→        let adjusted_state = if workload.thermal_headroom < 0.3 {
   195→            // 열 위험: 한 단계 낮춤
   196→            predicted_state.prev_state()
   197→        } else if workload.thermal_headroom > 0.8 && workload.ipc > 2.0 {
   198→            // 충분한 열 마진 + 높은 IPC: 한 단계 높임
   199→            predicted_state.next_state()
   200→        } else {
   201→            predicted_state
   202→        };
   203→
   204→        // 상태 변경 추적
   205→        if adjusted_state as u32 != self.current_state as u32 {
   206→            self.state_changes += 1;
   207→        }
   208→
   209→        self.current_state = adjusted_state;
   210→        self.prediction_history.push(adjusted_state);
   211→        self.predictions_made += 1;
   212→
   213→        adjusted_state
   214→    }
   215→
   216→    /// 예측 오차 측정
   217→    pub fn measure_prediction_error(&mut self, actual_state: DVFSState) -> f32 {
   218→        let predicted = self.current_state;
   219→
   220→        let error = ((predicted as u32) as i32 - (actual_state as u32) as i32).abs() as f32;
   221→        let max_error = 4.0;  // Min(0) ~ Max(4)
   222→
   223→        let error_percent = (error / max_error) * 100.0;
   224→        self.error_rate = error_percent;
   225→
   226→        error_percent
   227→    }
   228→
   229→    /// 예측 정확도 업데이트
   230→    pub fn update_accuracy(&mut self, correct_predictions: u32) {
   231→        if self.predictions_made > 0 {
   232→            self.prediction_accuracy = (correct_predictions as f32 / self.predictions_made as f32) * 100.0;
   233→        }
   234→    }
   235→
   236→    /// 통계
   237→    pub fn stats(&self) -> (u32, u32, f32, f32) {
   238→        (
   239→            self.predictions_made,
   240→            self.state_changes,
   241→            self.prediction_accuracy,
   242→            self.error_rate,
   243→        )
   244→    }
   245→}
   246→
   247→// ============================================================================
   248→// 4. DVFS 제어 인터페이스
   249→// ============================================================================
   250→
   251→pub struct DVFSController {
   252→    pub predictor: DVFSPredictor,
   253→    pub last_applied_state: DVFSState,
   254→    pub frequency_changes_per_sec: u32,
   255→    pub max_freq_changes_allowed: u32,  // 안정성 제약
   256→}
   257→
   258→impl DVFSController {
   259→    pub fn new() -> Self {
   260→        DVFSController {
   261→            predictor: DVFSPredictor::new(),
   262→            last_applied_state: DVFSState::Mid1GHz,
   263→            frequency_changes_per_sec: 0,
   264→            max_freq_changes_allowed: 10,  // 초당 최대 10회
   265→        }
   266→    }
   267→
   268→    /// DVFS 상태 적용 (MMIO 직접 제어)
   269→    pub fn apply_dvfs(&mut self, state: DVFSState) -> bool {
   270→        // 변경 빈도 제한 확인
   271→        if self.frequency_changes_per_sec >= self.max_freq_changes_allowed {
   272→            return false;
   273→        }
   274→
   275→        // 실제 구현: MMIO 쓰기
   276→        // *CPU_FREQ_CTRL = state.to_mhz();
   277→        // *CPU_VOLT_CTRL = state.to_voltage();
   278→
   279→        self.last_applied_state = state;
   280→        self.frequency_changes_per_sec += 1;
   281→
   282→        true
   283→    }
   284→
   285→    /// 워크로드 기반 자동 스케일링
   286→    pub fn auto_scale(&mut self, workload: &WorkloadProfile) -> DVFSState {
   287→        let predicted = self.predictor.predict_optimal_freq(workload);
   288→        let _ = self.apply_dvfs(predicted);
   289→        predicted
   290→    }
   291→}
