   232→
   233→pub struct ThermalPolicy {
   234→    pub warning_temp: f32,        // 경고 온도 (75°C)
   235→    pub critical_temp: f32,       // 비상 온도 (85°C)
   236→    pub shutdown_temp: f32,       // 종료 온도 (100°C)
   237→    pub target_temp: f32,         // 목표 온도 (65°C)
   238→}
   239→
   240→impl ThermalPolicy {
