   242→        ThermalPolicy {
   243→            warning_temp: 75.0,
   244→            critical_temp: 85.0,
   245→            shutdown_temp: 100.0,
   246→            target_temp: 65.0,
   247→        }
   248→    }
   249→
   250→    /// 정책 적용
   251→    pub fn apply(&self, manager: &mut ThermalManager, state: &mut ThermalState) -> bool {
   252→        // 자동 쓰로틀
   253→        let throttle = manager.auto_throttle(state);
   254→        state.throttle_level = throttle;
   255→
   256→        // 종료 온도 초과 시 false (시스템 shutdown)
   257→        state.die_temp_celsius < self.shutdown_temp
   258→    }
   259→}
