    15→#[derive(Clone, Copy, PartialEq)]
    16→pub enum ThreatType {
    17→    None = 0,           // 정상
    18→    PrivilegeEscalation = 1,  // 권한 상승
    19→    MemoryExploit = 2,  // 메모리 공격
    20→    FileExfiltration = 3,  // 파일 탈취
    21→    DirtyPipe = 4,     // Dirty Pipe 취약점
    22→    UnknownZeroDay = 5, // 알려지지 않은 공격
    23→}
    24→
    25→impl ThreatType {
    26→    pub fn to_u32(&self) -> u32 {
    27→        *self as u32
    28→    }
    29→
    30→    pub fn from_u32(val: u32) -> Option<ThreatType> {
    31→        match val {
    32→            0 => Some(ThreatType::None),
    33→            1 => Some(ThreatType::PrivilegeEscalation),
    34→            2 => Some(ThreatType::MemoryExploit),
    35→            3 => Some(ThreatType::FileExfiltration),
    36→            4 => Some(ThreatType::DirtyPipe),
    37→            5 => Some(ThreatType::UnknownZeroDay),
    38→            _ => None,
    39→        }
    40→    }
    41→
    42→    pub fn is_valid(&self) -> bool {
    43→        matches!(
    44→            self,
    45→            ThreatType::None
    46→                | ThreatType::PrivilegeEscalation
    47→                | ThreatType::MemoryExploit
    48→                | ThreatType::FileExfiltration
    49→                | ThreatType::DirtyPipe
    50→                | ThreatType::UnknownZeroDay
    51→        )
    52→    }
    53→}
