    60→    pub syscall_id: f32,          // 시스콜 ID (0-400)
    61→    pub arg_count: f32,           // 인자 개수
    62→    pub user_id: f32,             // 사용자 ID
    63→    pub process_id: f32,          // 프로세스 ID
