    78→impl SyscallFeatures {
    79→    pub fn new() -> Self {
    80→        SyscallFeatures {
    81→            syscall_id: 0.0,
    82→            arg_count: 0.0,
    83→            user_id: 0.0,
    84→            process_id: 0.0,
    85→            parent_pid: 0.0,
    86→            file_access_count: 0.0,
    87→            privilege_level: 0.0,
    88→            memory_access: 0.0,
    89→            suspicious_args: 0.0,
    90→            sequence_anomaly: 0.0,
