     1→// FreeLang Phase 7 Week 1 Days 5-7: Dynamic Priority Scheduler
     2→// 예측 기반 동적 우선순위 조정 및 스케줄링
     3→
     4→use std::collections::HashMap;
     5→
     6→// ============================================================================
     7→// Thread Priority Levels
     8→// ============================================================================
     9→
    10→#[derive(Debug, Clone, Copy, PartialEq, Eq, PartialOrd, Ord)]
    11→pub enum ThreadPriority {
    12→    Critical,              // 0 (OS 스레드, 커널)
    13→    HighRealtime,         // 1-49 (실시간 스레드)
    14→    NormalInteractive,    // 50-99 (사용자 상호작용)
    15→    NormalBatch,          // 100-139 (배치/백그라운드)
    16→    IdleNice,             // 140-199 (유휴/낮은 우선순위)
    17→}
    18→
    19→impl ThreadPriority {
    20→    pub fn to_u32(&self) -> u32 {
    21→        match self {
    22→            ThreadPriority::Critical => 0,
    23→            ThreadPriority::HighRealtime => 25,
    24→            ThreadPriority::NormalInteractive => 75,
    25→            ThreadPriority::NormalBatch => 120,
    26→            ThreadPriority::IdleNice => 170,
    27→        }
    28→    }
    29→
    30→    pub fn from_u32(value: u32) -> Self {
    31→        match value {
    32→            0..=10 => ThreadPriority::Critical,
    33→            11..=49 => ThreadPriority::HighRealtime,
    34→            50..=99 => ThreadPriority::NormalInteractive,
    35→            100..=139 => ThreadPriority::NormalBatch,
    36→            _ => ThreadPriority::IdleNice,
    37→        }
    38→    }
    39→}
    40→
    41→// ============================================================================
    42→// Thread Schedule Entry: 스레드 스케줄 항목
    43→// ============================================================================
    44→
    45→pub struct ThreadScheduleEntry {
    46→    thread_id: u32,
    47→    priority: ThreadPriority,
    48→    time_slice_ms: u32,            // 할당 시간 (ms)
    49→    boost_until: u64,              // 우선순위 부스트 기한 (timestamp)
    50→    io_wait_count: u32,            // I/O 대기 횟수
    51→    cpu_run_time_ms: u64,          // 누적 실행 시간
    52→    context_switch_count: u32,
    53→}
    54→
    55→impl ThreadScheduleEntry {
    56→    pub fn new(thread_id: u32, priority: ThreadPriority) -> Self {
    57→        ThreadScheduleEntry {
    58→            thread_id,
    59→            priority,
    60→            time_slice_ms: 4,  // 기본 4ms
    61→            boost_until: 0,
    62→            io_wait_count: 0,
    63→            cpu_run_time_ms: 0,
    64→            context_switch_count: 0,
    65→        }
    66→    }
    67→
    68→    pub fn is_boosted(&self, current_time: u64) -> bool {
    69→        self.boost_until > current_time
    70→    }
    71→
    72→    pub fn get_effective_priority(&self, current_time: u64) -> ThreadPriority {
    73→        if self.is_boosted(current_time) {
    74→            // 부스트 중: 우선순위 1-2 레벨 상향
    75→            let base = self.priority.to_u32();
    76→            let boosted = if base > 0 { base - 10 } else { 0 };
    77→            ThreadPriority::from_u32(boosted)
    78→        } else {
    79→            self.priority
    80→        }
    81→    }
    82→
    83→    pub fn should_preempt(&self, other: &ThreadScheduleEntry, current_time: u64) -> bool {
    84→        let my_effective = self.get_effective_priority(current_time);
    85→        let other_effective = other.get_effective_priority(current_time);
    86→
    87→        my_effective < other_effective  // 낮은 번호 = 높은 우선순위
    88→    }
    89→}
    90→
    91→impl Clone for ThreadScheduleEntry {
    92→    fn clone(&self) -> Self {
    93→        ThreadScheduleEntry {
    94→            thread_id: self.thread_id,
    95→            priority: self.priority,
    96→            time_slice_ms: self.time_slice_ms,
    97→            boost_until: self.boost_until,
    98→            io_wait_count: self.io_wait_count,
    99→            cpu_run_time_ms: self.cpu_run_time_ms,
   100→            context_switch_count: self.context_switch_count,
   101→        }
   102→    }
   103→}
   104→
   105→// ============================================================================
   106→// Dynamic Priority Scheduler: 동적 우선순위 스케줄러
   107→// ============================================================================
   108→
   109→pub struct DynamicPriorityScheduler {
   110→    threads: HashMap<u32, ThreadScheduleEntry>,
   111→    prediction_boost: bool,        // Phase 6 기반 부스트 활성화
   112→    current_time: u64,
   113→    total_schedules: u32,
   114→    starvation_threshold: u32,     // 기아 상태 판정 (실행 없이 N 스케줄)
   115→}
   116→
   117→impl DynamicPriorityScheduler {
   118→    pub fn new() -> Self {
   119→        DynamicPriorityScheduler {
   120→            threads: HashMap::new(),
   121→            prediction_boost: true,
   122→            current_time: 0,
   123→            total_schedules: 0,
   124→            starvation_threshold: 100,
   125→        }
   126→    }
   127→
   128→    // 패턴 예측 기반 우선순위 조정
   129→    pub fn adjust_priority_from_prediction(
   130→        &mut self,
   131→        thread_id: u32,
   132→        pattern: &str,
   133→        action: &str,
   134→    ) -> bool {
   135→        let mut entry = match self.threads.get(&thread_id) {
   136→            Some(e) => e.clone(),
   137→            None => ThreadScheduleEntry::new(thread_id, ThreadPriority::NormalInteractive),
   138→        };
   139→
   140→        // 패턴별 우선순위 조정
   141→        match pattern {
   142→            "MemoryLeak" => {
   143→                if action.contains("GC") {
   144→                    // GC 스레드: HighRealtime으로 부스트
   145→                    entry.priority = ThreadPriority::HighRealtime;
   146→                    entry.boost_until = self.current_time + 5000;  // 5초 부스트
   147→                    entry.time_slice_ms = 8;  // GC: 더 긴 시간 슬라이스
   148→                }
   149→            }
   150→            "IOBottleneck" => {
   151→                if action.contains("BufferPool") {
   152→                    // I/O 버퍼 관리: NormalInteractive
   153→                    entry.priority = ThreadPriority::NormalInteractive;
   154→                    entry.boost_until = self.current_time + 2000;
   155→                    entry.time_slice_ms = 4;
   156→                }
   157→            }
   158→            "ThreadContention" => {
   159→                // 동기화: 우선순위 약간 상향
   160→                if entry.priority > ThreadPriority::NormalInteractive {
   161→                    entry.priority = ThreadPriority::NormalInteractive;
   162→                    entry.time_slice_ms = 2;  // 더 짧은 시간 슬라이스
   163→                }
   164→            }
   165→            _ => {}
   166→        }
   167→
   168→        self.threads.insert(thread_id, entry);
   169→        true
   170→    }
   171→
   172→    // 우선순위 레벨에 따른 시간 슬라이스 계산
   173→    pub fn calculate_time_slice(&self, priority: ThreadPriority) -> u32 {
   174→        match priority {
   175→            ThreadPriority::Critical => 100,        // 100ms (우선권)
   176→            ThreadPriority::HighRealtime => 10,     // 10ms
   177→            ThreadPriority::NormalInteractive => 4, // 4ms (기본)
   178→            ThreadPriority::NormalBatch => 2,       // 2ms
   179→            ThreadPriority::IdleNice => 1,          // 1ms
   180→        }
   181→    }
   182→
   183→    // 메모리 복구 스레드 부스트
   184→    pub fn boost_memory_recovery_threads(&mut self, pattern: &str) {
   185→        if pattern != "MemoryLeak" {
   186→            return;
   187→        }
   188→
   189→        // 모든 GC 관련 스레드를 찾아 우선순위 상향
   190→        for (_, entry) in self.threads.iter_mut() {
   191→            if entry.thread_id % 10 == 0 {  // 예: GC 스레드는 특정 ID 패턴
   192→                entry.priority = ThreadPriority::HighRealtime;
   193→                entry.boost_until = self.current_time + 10000;  // 10초
   194→            }
   195→        }
   196→    }
   197→
   198→    // CPU 친화성 힌트 적용
   199→    pub fn apply_cpu_affinity_hint(&mut self, thread_id: u32, preferred_cores: u32) -> bool {
   200→        if let Some(entry) = self.threads.get_mut(&thread_id) {
   201→            // 선호 코어가 많을수록 더 자유로운 스케줄
   202→            if preferred_cores < 2 {
   203→                entry.time_slice_ms = 2;  // 제약이 많음: 짧은 슬라이스
   204→            } else if preferred_cores >= 8 {
   205→                entry.time_slice_ms = 8;  // 자유로움: 긴 슬라이스
   206→            }
   207→            true
   208→        } else {
   209→            false
   210→        }
   211→    }
   212→
   213→    // 스케줄 공정성 점수 계산 (0.0-1.0)
   214→    pub fn get_schedule_fairness_score(&self) -> f64 {
   215→        if self.threads.is_empty() {
   216→            return 1.0;
   217→        }
   218→
   219→        let mut cpu_times: Vec<_> = self.threads.values().map(|e| e.cpu_run_time_ms).collect();
   220→        cpu_times.sort();
   221→
   222→        if cpu_times.len() < 2 {
   223→            return 1.0;
   224→        }
   225→
   226→        // 최소/최대 비율 계산
   227→        let min = cpu_times[0] as f64;
   228→        let max = cpu_times[cpu_times.len() - 1] as f64;
   229→
   230→        if max == 0.0 {
   231→            return 1.0;
   232→        }
   233→
   234→        // 비율이 1.0에 가까울수록 공정함 (1.0 = 완벽 공정)
   235→        1.0 - ((max - min) / max * 0.5).min(1.0)
   236→    }
   237→
   238→    // 다음 실행할 스레드 선택
   239→    pub fn select_next_thread(&self) -> Option<u32> {
   240→        self.threads
   241→            .values()
   242→            .min_by_key(|entry| {
   243→                (
   244→                    entry.get_effective_priority(self.current_time).to_u32(),
   245→                    entry.cpu_run_time_ms,
   246→                )
   247→            })
   248→            .map(|e| e.thread_id)
   249→    }
   250→
   251→    // I/O 대기 종료 시 우선순위 부스트
   252→    pub fn handle_io_completion(&mut self, thread_id: u32) {
   253→        if let Some(entry) = self.threads.get_mut(&thread_id) {
   254→            entry.io_wait_count += 1;
   255→
   256→            // I/O 완료 후 우선순위 부스트 (응답성 개선)
   257→            if entry.io_wait_count > 5 {
   258→                entry.priority = ThreadPriority::NormalInteractive;
   259→                entry.boost_until = self.current_time + 1000;  // 1초 부스트
   260→            }
   261→        }
   262→    }
   263→
   264→    // 기아 상태(Starvation) 감지
   265→    pub fn detect_starvation(&self) -> Vec<u32> {
   266→        let mut starving = vec![];
   267→
   268→        for (_, entry) in self.threads.iter() {
   269→            if entry.context_switch_count > self.starvation_threshold {
   270→                // 너무 많이 컨텍스트 스위칭되었는데 실행 시간이 적음
   271→                if entry.cpu_run_time_ms < 10 {
   272→                    starving.push(entry.thread_id);
   273→                }
   274→            }
   275→        }
   276→
   277→        starving
   278→    }
   279→
   280→    // 우선순위 역전(Priority Inversion) 감지
   281→    pub fn detect_priority_inversion(&self) -> Option<(u32, u32)> {
   282→        // 높은 우선순위 스레드가 낮은 우선순위 스레드를 기다리는 경우
   283→        // 이 구현에서는 간단한 휴리스틱만 사용
   284→
   285→        for (id1, entry1) in self.threads.iter() {
   286→            for (id2, entry2) in self.threads.iter() {
   287→                if entry1.priority < entry2.priority && entry2.cpu_run_time_ms > entry1.cpu_run_time_ms {
   288→                    return Some((*id1, *id2));
   289→                }
   290→            }
   291→        }
   292→
   293→        None
   294→    }
   295→
   296→    // 시간 경과
   297→    pub fn advance_time(&mut self, delta_ms: u32) {
   298→        self.current_time += delta_ms as u64;
   299→        self.total_schedules += 1;
   300→
   301→        // 모든 부스트 상태 업데이트
   302→        for entry in self.threads.values_mut() {
   303→            entry.cpu_run_time_ms += delta_ms as u64;
   304→            entry.context_switch_count += 1;
   305→        }
   306→    }
   307→
   308→    // 스케줄 상태 조회
   309→    pub fn get_schedule_status(&self, thread_id: u32) -> Option<(ThreadPriority, u32, u64)> {
   310→        self.threads.get(&thread_id).map(|e| {
   311→            (
   312→                e.get_effective_priority(self.current_time),
   313→                e.time_slice_ms,
   314→                e.cpu_run_time_ms,
   315→            )
   316→        })
   317→    }
   318→
   319→    // 스레드 등록
   320→    pub fn register_thread(&mut self, thread_id: u32, priority: ThreadPriority) {
   321→        self.threads
   322→            .insert(thread_id, ThreadScheduleEntry::new(thread_id, priority));
   323→    }
   324→}
